import java.io.*;

public class WriteSerialized {
  public static void main(String[] args) {
    try {
      // 第一步：造一条连接流，连到文件；文件不存在就自动创建
      FileOutputStream fileStream = new FileOutputStream("MyGame.ser");
      // 第二步：造一条链流，挂到连接流上
      ObjectOutputStream os = new ObjectOutputStream(fileStream);
      // 第三步：按顺序写三个对象，不需要碰底下的 fileStream
      os.writeObject(characterOne);
      os.writeObject(characterTwo);
      os.writeObject(characterThree);
      // 第四步：关最上层，整条链连同文件一起关闭
      os.close();
    } catch (IOException ex) {   // I/O 随时可能出问题，必须处理异常
      ex.printStackTrace();
    }
  }
}

import java.io.*;

// 演示「链」的概念：对象 → ObjectOutputStream → FileOutputStream → 文件
public class ChainDemo {
  public static void main(String[] args) throws IOException {
    // 连接流：它的职责只有一件——连到文件并写字节
    FileOutputStream connection = new FileOutputStream("demo.ser");
    // 链流：它的职责也只有一件——把对象变成可写的字节数据
    ObjectOutputStream chain = new ObjectOutputStream(connection);
    // 我们只对链流下命令，连接流在底下默默配合
    chain.writeObject("一个字符串对象");
    // 关掉顶层即可，链底下的连接流会被自动关闭
    chain.close();
  }
}

