import java.io.*;

public class Square implements Serializable {   // 标记接口：一个方法都不用实现
  private int width;
  private int height;
  public Square(int width, int height) {
    this.width = width;
    this.height = height;
  }
  public static void main(String[] args) {
    Square mySquare = new Square(50, 20);
    try {
      FileOutputStream fs = new FileOutputStream("foo.ser");
      ObjectOutputStream os = new ObjectOutputStream(fs);
      os.writeObject(mySquare);   // 参数类型是 Object，编译期不查可序列化性
      os.close();
    } catch (Exception ex) {
      ex.printStackTrace();       // 运行时可能抛 NotSerializableException
    }
  }
}

